package local.bbsgeoimporter;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import com.google.gson.*;
final class StartupOutputAcceptance {
 static void check(boolean b,String m){ImporterAcceptance.check(b,m);}
 static void remove(Path fixture,Path path)throws Exception{if(!path.toAbsolutePath().normalize().startsWith(fixture.toAbsolutePath().normalize()))throw new AssertionError("unsafe fixture deletion");if(Files.exists(path))try(var walk=Files.walk(path)){for(Path p:walk.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
 static void boot(Path config,List<GeoImporter.ModSource> sources,boolean setupFirst)throws Exception{List<String> logs=new ArrayList<>();var service=new ScanService(config,()->sources,logs::add);try{Performance.reset();if(setupFirst)service.startup();var ready=service.prepare(null,Runnable::run).get();service.apply(ready);if(!setupFirst)service.startup();for(int i=0;i<5;i++)service.apply(ready);service.request().get(12,TimeUnit.SECONDS);check(service.status().contains("ready"),"automatic startup completed: "+logs);check(PerformanceAcceptance.count("import.scan")==1,"setup/reload order and duplicate events run one scan");}finally{PerformanceAcceptance.stop(service);}}
 static Map<Path,String> outputs(Path config)throws Exception{Map<Path,String> result=new HashMap<>();JsonObject state=ImporterAcceptance.json(config.resolve("bbs/model-import-index.json"));for(var owner:state.getAsJsonObject("mods").entrySet()){var mod=owner.getValue().getAsJsonObject();for(var f:mod.getAsJsonObject("files").entrySet()){var record=f.getValue().getAsJsonObject();if(record.has("writtenHash"))result.put(config.resolve("bbs/assets/models").resolve(mod.get("directory").getAsString()).resolve(record.get("target").getAsString()),record.get("writtenHash").getAsString());}}return result;}
 static void verify(Path config,Map<Path,String> expected)throws Exception{for(var e:expected.entrySet())check(Files.isRegularFile(e.getKey())&&GeoImporter.hash(Files.readAllBytes(e.getKey())).equals(e.getValue()),"startup recreated exact owned Geo/PNG/animation: "+e.getKey());check(ImportedModelGroups.modelKeys().size()>=2,"repaired outputs BBS enumerable with mod categories");BbsCpuAcceptance.run(config.resolve("bbs/assets"),SharedModelAssets.bindingsForTest());}
 static void run(Path base)throws Exception{Path config=base.resolve("config"),one=base.resolve("one"),two=base.resolve("two");JsonObject shape=JsonParser.parseString(ImporterAcceptance.GEO).getAsJsonObject();shape.getAsJsonArray("minecraft:geometry").get(0).getAsJsonObject().getAsJsonArray("bones").add(JsonParser.parseString("{ "+(char)34+"name"+(char)34+":"+(char)34+"root"+(char)34+","+(char)34+"pivot"+(char)34+":[0,0,0],"+(char)34+"cubes"+(char)34+":[]} "));shape.addProperty("texture","shared:textures/p.png");String geo=shape.toString();ImporterAcceptance.put(one.resolve("assets/shared/geo/a.geo.json"),geo);ImporterAcceptance.png(one.resolve("assets/shared/textures/p.png"),0xff123456);ImporterAcceptance.put(two.resolve("assets/second/geo/b.geo.json"),ImporterAcceptance.GEO);var sources=new ArrayList<>(List.of(ImporterAcceptance.source("source_one","Same Display",one),ImporterAcceptance.source("source_two","Same Display",two)));
 boot(config,sources,true);var expected=outputs(config);check(expected.size()>=3,"fresh startup creates real models and PNG, not empty directories");verify(config,expected);var plans=Map.copyOf(SharedModelAssets.bindingsForTest());byte[] index=Files.readAllBytes(config.resolve("bbs/model-import-index.json"));
 remove(base,config.resolve("bbs/assets/models"));boot(config,sources,false);verify(config,expected);check(plans.equals(SharedModelAssets.bindingsForTest()),"whole managed root recovery restores complete texture plans");check(PerformanceAcceptance.count("catalog.build")==0,"missing root uses parsed cache but checks actual outputs");
 Path mod=expected.keySet().iterator().next();while(!mod.getParent().equals(config.resolve("bbs/assets/models")))mod=mod.getParent();remove(base,mod);boot(config,sources,true);verify(config,expected);
 for(Path p:expected.keySet())if(p.toString().endsWith(".png")||p.toString().endsWith(".geo.json"))Files.delete(p);boot(config,sources,false);verify(config,expected);
 index=Files.readAllBytes(config.resolve("bbs/model-import-index.json"));boot(config,sources,true);check(PerformanceAcceptance.count("catalog.build")==0&&PerformanceAcceptance.count("index.commit")==0&&PerformanceAcceptance.count("import.read")==0,"unchanged restart checks outputs without reparse/rewrite/reread source files");check(Arrays.equals(index,Files.readAllBytes(config.resolve("bbs/model-import-index.json"))),"repair and unchanged restart preserve exact index");
 Path third=base.resolve("new");ImporterAcceptance.put(third.resolve("assets/newmod/geo/new.geo.json"),ImporterAcceptance.GEO);sources.add(ImporterAcceptance.source("new_never_seen","Same Display",third));boot(config,sources,false);check(ImportedModelGroups.modelKeys().size()==3,"new mod discovered on next automatic startup despite existing caches");
 Path user=expected.keySet().stream().filter(p->p.toString().endsWith(".geo.json")).findFirst().orElseThrow();Files.writeString(user,"user edited");boot(config,sources,true);check(Files.readString(user).equals("user edited"),"startup preserves user modified files");var isolated=new ScanService(base.resolve("failed-extra"),()->sources,x->{});try{var badExtra=new EffectiveResources.Reader(){public ResourceEvidence.Snapshot read(long g,String address)throws Exception{int colon=address.indexOf(58);String rel="assets/"+address.substring(0,colon)+"/"+address.substring(colon+1);for(var source:sources)for(Path root:source.roots())if(Files.isRegularFile(root.resolve(rel)))return new ResourceEvidence.Snapshot(g,address,source.id(),Files.readAllBytes(root.resolve(rel)));return null;}public Set<String> addresses(){throw new IllegalStateException("fixture failed extra enumeration");}};isolated.startup();var prepared=new ReloadSnapshot(RuntimeCapture.generation(),sources,badExtra);isolated.apply(prepared);isolated.request().get(12,TimeUnit.SECONDS);check(isolated.status().contains("ready"),"failed additional resources do not block raw loaded Mod import");check(ImportedModelGroups.modelKeys().size()==3,"all loaded Geo mods visible despite supplement enumeration failure");}finally{PerformanceAcceptance.stop(isolated);}System.out.println("STARTUP OUTPUT PASS: fresh/root missing/mod missing/Geo+PNG missing/new mod/hot/both event orders/user protection");}
}
